import { useRef, useState } from "react";
import { ImageIcon, Upload } from "lucide-react";

// Stub — wire this up to your actual "resume analysis" agent endpoint later.
async function sendToResumeAnalysisAgent(file) {
  console.log("Sending to resume analysis agent:", file.name);

  // Example of what this might look like once the agent exists:
  // const formData = new FormData();
  // formData.append("resume", file);
  // const res = await fetch("/api/agents/resume-analysis", {
  //   method: "POST",
  //   body: formData,
  // });
  // return res.json();
}

export default function Home() {
  const fileInputRef = useRef(null);
  const [fileName, setFileName] = useState(null);
  const [status, setStatus] = useState("idle"); // idle | sending | sent | error

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== "application/pdf") {
      setStatus("error");
      setFileName(null);
      return;
    }

    setFileName(file.name);
    setStatus("sending");

    try {
      await sendToResumeAnalysisAgent(file);
      setStatus("sent");
    } catch (err) {
      console.error(err);
      setStatus("error");
    } finally {
      // allow re-selecting the same file later
      e.target.value = "";
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-6 py-16 flex flex-col items-center text-center">
      <h1 className="text-3xl font-semibold text-stone-900 mb-3">Home</h1>
      <p className="text-stone-600 leading-relaxed mb-10">
        This is the home page. Swap this content out for whatever your app
        needs to show first.
      </p>

      <div className="w-full max-w-sm aspect-square rounded-lg border border-dashed border-stone-300 bg-stone-100 flex items-center justify-center mb-6">
        <ImageIcon size={40} className="text-stone-400" />
      </div>

      <button
        onClick={handleUploadClick}
        className="flex items-center gap-2 px-4 h-10 rounded-md text-sm font-medium bg-stone-900 text-white hover:bg-stone-800 transition-colors"
      >
        <Upload size={16} />
        Upload resume
      </button>

      <input
        ref={fileInputRef}
        type="file"
        accept="application/pdf"
        onChange={handleFileChange}
        className="hidden"
      />

      {fileName && status !== "error" && (
        <p className="text-sm text-stone-500 mt-3">
          {status === "sending" && `Sending "${fileName}" to resume analysis…`}
          {status === "sent" && `"${fileName}" sent to resume analysis.`}
        </p>
      )}
      {status === "error" && (
        <p className="text-sm text-red-600 mt-3">
          Please upload a PDF file.
        </p>
      )}
    </div>
  );
}
